// or load it at runtime straight from the CDN:
using GLTFast;
var gltf = new GltfImport();
if (await gltf.Load("https://cdn.3dassets.dev/assets/19141/v1/model.glb")) await gltf.InstantiateMainSceneAsync(transform);

usage.threejs:
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js'

const loader = new GLTFLoader()
loader.load('https://cdn.3dassets.dev/assets/19142/v1/model.glb', (gltf) => {
  scene.add(gltf.scene)
})

usage.r3f:
import { useGLTF } from '@react-three/drei'

export function ClubTrophyDisplayPlinthFootballSoccerStadiumAndClubGrounds(props) {
  const { scene } = useGLTF('https://cdn.3dassets.dev/assets/19142/v1/model.glb')
  return <primitive object={scene} {...props} />
}
useGLTF.preload('https://cdn.3dassets.dev/assets/19142/v1/model.glb')

